 const handleNotificationResponse=async(response:Notifications.NotificationResponse)=>{
  const payload=response.notification.request.content.data;
  if(payload?.app!=='sehat-parivaar'||typeof payload.medicineId!=='string'||typeof payload.scheduledAt!=='string')return;
  if(response.actionIdentifier==='TAKEN'){
   await recordDoseResponse(payload.medicineId,payload.scheduledAt,'taken',undefined,response.notification.request.identifier);
  }else if(response.actionIdentifier==='NOT_TAKEN'){
   askNotTakenReason(payload.medicineId,payload.scheduledAt,response.notification.request.identifier);
  }else if(response.actionIdentifier==='SNOOZE'){
   await snooze(payload.medicineId,payload.scheduledAt,response.notification.request.identifier);
  }else{
   const current=dataRef.current;
   const medicine=current?.medicines.find(item=>item.id===payload.medicineId);
   const dose=current?.doseLogs.find(item=>item.medicineId===payload.medicineId&&item.scheduledAt===payload.scheduledAt);
   if(medicine&&dose?.status!=='taken'&&dose?.status!=='skipped'){
    setTab('today');setActiveReminder({medicineId:payload.medicineId,scheduledAt:payload.scheduledAt,notificationId:response.notification.request.identifier});
   }
  }
 };
