   <Text style={[alarmStyles.time,text(25)]}>{new Date(activeReminder.scheduledAt).toLocaleTimeString(lang==='hi'?'hi-IN':'en-IN',{hour:'2-digit',minute:'2-digit',hour12:false})}</Text>
