   {secondary(trn('Refresh scheduled reminders','रिमाइंडर रीफ़्रेश करें'),()=>void(async()=>{try{const readiness=await requestReminderPermissions();setReminderReadiness(readiness);await reconcileReminders(data);Alert.alert(readiness.granted&&readiness.channelReady?trn('Reminder settings checked','रिमाइंडर सेटिंग जाँची गई'):trn('Reminder access needs attention','रिमाइंडर अनुमति जाँचें'),readiness.granted&&readiness.channelReady?trn('Upcoming reminders were reconciled on this phone. Android exact-alarm access is not exposed by Expo and may need separate approval.','आने वाले रिमाइंडर इस फ़ोन पर मिलाए गए। Expo exact-alarm अनुमति नहीं बता सकता; इसकी अलग अनुमति चाहिए हो सकती है।'):trn('Enable notifications and the medicine alarm channel in Android settings.','Android सेटिंग्स में नोटिफ़िकेशन और दवा अलार्म चैनल चालू करें।'));}catch(error){Alert.alert(trn('Could not refresh reminders','रिमाइंडर रीफ़्रेश नहीं हुए'),String(error));}})())}
